#!/usr/bin/env python3
import sys, os, re, gzip, io, csv, json
import xml.etree.ElementTree as ET
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, getcontext, ROUND_HALF_UP

getcontext().prec = 60
FACT = {'kg': Decimal(1), 'g': Decimal('0.001'), 'lb': Decimal('0.45359237'),
        'oz': Decimal('0.028349523125')}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
MONTHS = {m: i + 1 for i, m in enumerate(
    'jan feb mar apr may jun jul aug sep oct nov dec'.split())}


def decode(b):
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8', 'replace')
    if b[:2] in (b'\xff\xfe', b'\xfe\xff'):
        return b.decode('utf-16', 'replace')
    enc = 'utf-8'
    head = b[:2000]
    m = re.search(rb'(?im)^#\s*charset\s*:\s*([A-Za-z0-9_.:-]+)', head)
    if m:
        try:
            enc = m.group(1).decode('ascii')
            ''.encode(enc)
        except Exception:
            enc = 'utf-8'
    return b.decode(enc, 'replace')


def id_num(s):
    m = re.match(r'^\s*SH\D*0*(\d+)\s*$', s or '', re.I)
    return int(m.group(1)) if m else None


def norm_status(s):
    return re.sub(r'[\s\-]+', '_', (s or '').strip().lower())


COUNTED = {'delivered', 'delivered_late'}
HSTATE = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled',
          'RET': 'returned', 'HLD': 'held'}
FWSTATE = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled',
           'R': 'returned', 'H': 'held'}


def rtype(s):
    s = (s or '').strip().lower()
    if s.startswith('v'):
        return 'void'
    if s.startswith('c') or s.startswith('a'):
        return 'correction'
    return 'new'


def parse_date(s, form):
    """returns a date (UTC) or datetime converted to UTC date"""
    s = s.strip()
    m = re.match(r'^(\d{4})-(\d\d)-(\d\d)[T ](.*)$', s)
    if m:
        try:
            dt = datetime.fromisoformat(s.replace(' ', 'T', 1))
        except ValueError:
            dt = datetime.fromisoformat(s[:10])
        if dt.tzinfo is not None:
            dt = dt.astimezone(timezone.utc)
        return dt.date()
    f = (form or '').strip()
    fl = f.lower()
    if re.match(r'^\d{4}-\d\d-\d\d$', s) and fl in ('', 'iso', 'ymd', 'yyyy-mm-dd'):
        return date(int(s[:4]), int(s[5:7]), int(s[8:10]))
    if fl == 'serial':
        return date(1899, 12, 31) + timedelta(days=int(float(s)) - 1)
    if fl in ('dmy', 'dd-mm-yyyy'):
        d, mo, y = re.split(r'[-/.]', s)
        return date(int(y), int(mo), int(d))
    if fl == 'mm/dd/yyyy':
        mo, d, y = s.split('/')
        return date(int(y), int(mo), int(d))
    if fl == 'dd/mm/yyyy':
        d, mo, y = s.split('/')
        return date(int(y), int(mo), int(d))
    if fl in ('dd.mm.yyyy',):
        d, mo, y = s.split('.')
        return date(int(y), int(mo), int(d))
    if fl == 'yyyymmdd':
        return date(int(s[:4]), int(s[4:6]), int(s[6:8]))
    if fl == 'yyyyddd':
        return date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:7]) - 1)
    # fallbacks by shape
    if re.match(r'^\d{4}-\d\d-\d\d$', s):
        return date(int(s[:4]), int(s[5:7]), int(s[8:10]))
    m = re.match(r'^(\d{1,2}) ([A-Za-z]{3})[a-z]* (\d{4})$', s)
    if m:
        return date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    raise ValueError('date %r form %r' % (s, form))


def parse_weight(text, unit, dec):
    """text may contain its own unit. dec: 'dot' or 'comma'."""
    t = text.strip()
    m = re.match(r'^([-+]?[\d.,\s]*\d)\s*([A-Za-z]*)$', t)
    if not m:
        raise ValueError('weight %r' % text)
    num, u = m.group(1).replace(' ', ''), m.group(2).lower()
    if dec == 'comma':
        num = num.replace('.', '').replace(',', '.')
    else:
        num = num.replace(',', '')
    if u in FACT:
        unit = u
    return Decimal(num) * FACT[unit]


def unit_of(v, default='kg'):
    m = re.match(r'\s*([A-Za-z]+)', v or '')
    if m and m.group(1).lower() in FACT:
        return m.group(1).lower()
    return default


# ---- parsers: each returns (seq, [records]) record = (num, type, status, kg, date)

def parse_delimited(text, depot):
    cfg = {
        'east': dict(delim=',', quote=True, cols='id type shipped gross net status note'.split(),
                     idc='id', typ='type', ship='shipped', wt=['gross'], st='status',
                     dec='dot', unit='kg', form='YMD'),
        'lakeside': dict(delim=',', quote=True, cols='id kind booked shipped gross_kg net_kg status'.split(),
                         idc='id', typ='kind', ship='shipped', wt=['gross_kg'], st='status',
                         dec='dot', unit='kg', form='iso'),
        'harbor': dict(delim='|', quote=False, cols='rec ref date weight state'.split(),
                       idc='ref', typ='rec', ship='date', wt=['weight'], st='state',
                       dec='dot', unit='kg', form='iso'),
        'river': dict(delim='\t', quote=False, cols='t ref shipped weight status'.split(),
                      idc='ref', typ='t', ship='shipped', wt=['weight'], st='status',
                      dec='dot', unit='kg', form='MM/DD/YYYY'),
        'west': dict(delim=';', quote=False, cols='id typ shipped weight status note'.split(),
                     idc='id', typ='typ', ship='shipped', wt=['weight'], st='status',
                     dec='comma', unit='kg', form='DD.MM.YYYY'),
    }[depot]
    text = text.replace('\r\n', '\n').replace('\r', '\n')
    if cfg['quote']:
        rows = csv.reader(io.StringIO(text, newline=''), delimiter=cfg['delim'])
    else:
        rows = (l.split(cfg['delim']) for l in text.split('\n'))
    seq = None
    unit = cfg['unit']
    form = cfg['form']
    header = None
    recs = []
    colset = set(cfg['cols'])
    for r in rows:
        if not r or all(not x.strip() for x in r):
            continue
        first = r[0]
        if first.startswith('#'):
            line = cfg['delim'].join(r).strip()
            m = re.match(r'^#\s*([^:=]+?)\s*:\s*(.*)$', line)
            if m:
                name, val = m.group(1).lower(), m.group(2).strip()
                if name == 'seq':
                    seq = int(re.match(r'\d+', val).group())
                elif name in ('unit', 'weight unit'):
                    unit = unit_of(val, unit)
                elif name in ('dates', 'date format'):
                    form = val
                continue
            m = re.search(r'seq\s*=\s*(\d+)', line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        names = [x.strip().lower() for x in r]
        if all(n in colset for n in names):
            header = names
            continue
        if header is None:
            header = cfg['cols']
        row = [x for x in r]
        n = len(header)
        if len(row) == n + 1:
            wi = [i for i, h in enumerate(header) if h in cfg['wt']]
            if not wi:
                continue
            i = wi[0]
            ru = row[i + 1].strip().lower()
            row = row[:i + 1] + row[i + 2:]
            rowunit = ru if ru in FACT else None
        elif len(row) == n:
            rowunit = None
        else:
            continue
        d = dict(zip(header, row))
        num = id_num(d.get(cfg['idc'], ''))
        if num is None:
            continue
        t = rtype(d.get(cfg['typ'], ''))
        if t == 'void':
            recs.append((num, t, None, None, None))
            continue
        wcol = [h for h in header if h in cfg['wt']][0]
        u = unit
        if depot == 'lakeside':
            u = 'kg'
        if rowunit:
            u = rowunit
        kg = parse_weight(d[wcol], u, cfg['dec'])
        st = d[cfg['st']]
        st = HSTATE.get(st.strip().upper(), norm_status(st)) if depot == 'harbor' else norm_status(st)
        dt = parse_date(d[cfg['ship']], form)
        recs.append((num, t, st, kg, dt))
    return seq, recs


def parse_json(text):
    seq = None
    recs = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        try:
            v = json.loads(line)
        except ValueError:
            continue
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if seq is None and 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                continue
            num = id_num(str(o.get('id', '')))
            if num is None:
                continue
            t = rtype(o.get('kind'))
            if t == 'void':
                recs.append((num, t, None, None, None))
                continue
            kg = None
            for k, val in o.items():
                m = re.match(r'^weight_(kg|g|lb|oz)$', k)
                if m:
                    kg = Decimal(str(val)) * FACT[m.group(1)]
            if kg is None and 'weight' in o:
                kg = parse_weight(str(o['weight']), 'kg', 'dot')
            recs.append((num, t, norm_status(o.get('status')), kg,
                         parse_date(o['shipped_at'], 'iso')))
    return seq, recs


def parse_xml(text):
    text = re.sub(r'^\s*<\?xml[^>]*\?>', '', text)
    root = ET.fromstring(text)
    seq = int(root.get('seq')) if root.get('seq') else None
    runit = unit_of(root.get('weight-unit'), 'kg')
    recs = []
    for sh in root.iter('shipment'):
        num = id_num(sh.get('id', ''))
        if num is None:
            continue
        t = rtype(sh.get('type'))
        if t == 'void':
            recs.append((num, t, None, None, None))
            continue

        def get(name):
            if sh.get(name) is not None:
                return sh.get(name)
            e = sh.find(name)
            return e.text if e is not None and e.text else None
        we = sh.find('weight')
        if we is not None:
            u = unit_of(we.get('unit'), runit)
            kg = parse_weight(we.text, u, 'dot')
        else:
            kg = parse_weight(sh.get('weight'), runit, 'dot')
        recs.append((num, t, norm_status(get('status')), kg,
                     parse_date(get('shipped').strip(), 'iso')))
    return seq, recs


FW = {
    'FW1': (42, lambda l: dict(id=l[0:9], type=l[9], sh=l[10:17], w=l[17:25], st=l[25]), 'YYYYDDD', 'g'),
    'FW2': (43, lambda l: dict(type=l[0], id=l[1:10], sh=l[10:18], w=l[18:26], st=l[26]), 'YYYYMMDD', 'cg'),
    'FW3': (41, lambda l: dict(id=l[0:9], sh=l[9:16], type=l[16], w=l[17:24], st=l[24]), 'YYYYDDD', 'dlb'),
}


def parse_fixed(text):
    seq = None
    layout = None
    bylen = {v[0]: k for k, v in FW.items()}
    recs = []
    for line in text.replace('\r', '').split('\n'):
        if line.startswith('\x0c') or 'SHIPMENT LISTING' in line:
            continue
        if line.startswith('#LAYOUT'):
            layout = line.split()[1].strip()
            continue
        if line.startswith('#SEQ'):
            seq = int(line.split()[1])
            continue
        if line.startswith('#') or not line.strip():
            continue
        L = len(line)
        name = bylen.get(L, layout)
        if name not in FW:
            continue
        if L != FW[name][0]:
            line = line.ljust(FW[name][0])
        f = FW[name][1](line)
        num = id_num(f['id'])
        if num is None:
            continue
        t = rtype(f['type'])
        if t == 'void':
            recs.append((num, t, None, None, None))
            continue
        w = int(f['w'])
        kind = FW[name][3]
        if kind == 'g':
            kg = Decimal(w) * FACT['g']
        elif kind == 'cg':
            kg = Decimal(w) / 100
        else:
            kg = Decimal(w) / 10 * FACT['lb']
        recs.append((num, t, FWSTATE.get(f['st'].strip().upper(), ''), kg,
                     parse_date(f['sh'], FW[name][2])))
    return seq, recs


def parse_file(path, depot):
    with open(path, 'rb') as fh:
        b = fh.read()
    text = decode(b)
    stripped = text.lstrip('\ufeff \n\r\t')
    if depot == 'central' or stripped.startswith('<'):
        return parse_xml(text)
    if depot == 'north':
        return parse_json(text)
    if depot == 'south':
        return parse_fixed(text)
    return parse_delimited(text, depot)


def main():
    data, out = sys.argv[1], sys.argv[2]
    files = {}
    for n in sorted(os.listdir(data)):
        p = os.path.join(data, n)
        if os.path.isfile(p):
            files.setdefault(n.split('-')[0], []).append(p)
    corrections = resends = 0
    current = {}
    for depot, paths in files.items():
        exports = []
        for i, p in enumerate(paths):
            seq, recs = parse_file(p, depot)
            exports.append((seq if seq is not None else -1, i, recs))
        exports.sort(key=lambda e: (e[0], e[1]))
        cur = {}
        for _, _, recs in exports:
            for num, t, st, kg, dt in recs:
                if t == 'new':
                    if num in cur:
                        resends += 1
                    else:
                        cur[num] = (st, kg, dt)
                elif t == 'correction':
                    cur[num] = (st, kg, dt)
                    corrections += 1
                else:
                    cur.pop(num, None)
                    corrections += 1
        current[depot] = cur
    rank = {d: i for i, d in enumerate(ORDER)}
    owners = {}
    for depot in sorted(current, key=lambda d: rank.get(d, 99)):
        for num in current[depot]:
            owners.setdefault(num, []).append(depot)
    handovers = sum(1 for v in owners.values() if len(v) > 1)
    dep = {d: [0, Decimal(0)] for d in files}
    mon = {}
    for num, ds in owners.items():
        d = ds[0]
        st, kg, dt = current[d][num]
        if st in COUNTED:
            dep[d][0] += 1
            dep[d][1] += kg
            k = '%04d-%02d' % (dt.year, dt.month)
            m = mon.setdefault(k, [0, Decimal(0)])
            m[0] += 1
            m[1] += kg

    def r(x):
        return float(x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    res = {
        'depots': {d: {'shipments': v[0], 'total_kg': r(v[1])} for d, v in sorted(dep.items())},
        'months': {k: {'shipments': v[0], 'total_kg': r(v[1])} for k, v in sorted(mon.items())},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out, 'w') as fh:
        json.dump(res, fh, indent=2)


main()
